<template><div v-if="allowed" class="right-menu-item hover-effect" style="display:flex;align-items:center" @click="visible=true" role="button" tabindex="0" aria-label="门户站内消息" @keydown.enter="visible=true"><el-badge :value="count" :max="99" :hidden="!count"><svg-icon icon-class="bell"/></el-badge><el-drawer v-model="visible" title="门户站内消息" size="min(900px,95vw)" append-to-body destroy-on-close><NotificationList @changed="refresh" @open="visible=false"/></el-drawer></div></template>
<script setup>
import{ref,computed,onMounted,onBeforeUnmount,watch}from'vue';import auth from '@/plugins/auth';import{getToken}from'@/utils/auth';import{workflow}from'@/api/cms/workflow';import NotificationList from '@/views/cms/components/NotificationList.vue';import useUserStore from '@/store/modules/user'
const user=useUserStore(),allowed=computed(()=>!!user.token&&auth.hasPermi('cms:notification:list')),visible=ref(false),count=ref(0);let epoch=0,timer,flight=false,controller
async function refresh(){if(flight||!allowed.value||document.hidden)return;const n=epoch,token=getToken();flight=true;controller=new AbortController();try{const request=(await import('@/utils/request')).default;const r=await request({url:'/cms/notifications/unread',signal:controller.signal});if(n===epoch&&token===getToken()&&allowed.value)count.value=r.data}catch{if(n===epoch)count.value=0}finally{flight=false}}
function reset(){++epoch;controller?.abort();count.value=0;visible.value=false}watch(()=>user.token,()=>{reset();refresh()});watch(allowed,()=>{reset();refresh()});onMounted(()=>{refresh();timer=setInterval(refresh,15000);document.addEventListener('visibilitychange',refresh)});onBeforeUnmount(()=>{reset();clearInterval(timer);document.removeEventListener('visibilitychange',refresh)})
</script>
